-- Module: seed_content_data
-- Seeds the four content tables with the curated Bangladesh-market dataset.
--
-- Source: the JSON datasets from the isar-frontend-data branch, converted to SQL.
-- Curated by Isar (dwijeshu003@gmail.com); the underlying research is theirs.
--
-- Idempotent: every statement is ON CONFLICT DO NOTHING and explicit ids are
-- preserved so cross-page links by id keep working. Sequences are re-synced
-- at the end so subsequent admin inserts do not collide with seeded ids.
--
-- Resource Bangla columns are intentionally NULL: the curated content is
-- English-only and Bangla translations are entered via the admin dashboard.

-- disciplines (7 rows)
ON CONFLICT (id) DO NOTHING;

-- career_paths (70 rows)
ON CONFLICT (id) DO NOTHING;

-- resources (42 rows, English only; *_bn left NULL)
-- Ids are assigned explicitly here: the source JSON had none, but the table
-- needs a stable key for ON CONFLICT idempotency and for admin edit/delete.
-- Note: the 42 rows reference only 23 distinct URLs — several guides are
-- deliberately listed against more than one discipline or category.
ON CONFLICT (id) DO NOTHING;

-- alumni (10 rows)
ON CONFLICT (id) DO NOTHING;

-- Re-sync SERIAL sequences past the explicitly-seeded ids.
SELECT setval('disciplines_id_seq',  (SELECT COALESCE(MAX(id), 1) FROM disciplines));
SELECT setval('career_paths_id_seq', (SELECT COALESCE(MAX(id), 1) FROM career_paths));
SELECT setval('resources_id_seq',    (SELECT COALESCE(MAX(id), 1) FROM resources));
SELECT setval('alumni_id_seq',       (SELECT COALESCE(MAX(id), 1) FROM alumni));
