INSERT INTO disciplines (id, name, description) VALUES
  (1, 'IT', 'Information Technology and Computer Science'),
  (2, 'Finance', 'Banking, Accounting, and Financial Services'),
  (3, 'Science', 'Pure and Applied Sciences'),
  (4, 'Engineering', 'Civil, Electrical, Mechanical and related'),
  (5, 'Business', 'Marketing, Management, and Commerce'),
