  (7, 'Education', 'Teaching and Educational Leadership')
INSERT INTO career_paths (id, title, industry, discipline, description, skills, progression, salary_entry, salary_senior) VALUES
  (1, 'Financial Analyst', 'Banking and Finance', 'Finance', 'Financial Analysts in Bangladesh are in high demand across banks, NGOs, and corporate finance teams. The role involves analysing financial data, preparing reports, and supporting business decisions.', '["Excel","Financial Modelling","Accounting","Data Analysis","Report Writing"]'::jsonb, '[{"label":"Junior Analyst","time":"0–1 yr"},{"label":"Financial Analyst","time":"1–3 yrs","current":true},{"label":"Senior Analyst","time":"3–5 yrs"},{"label":"Finance Manager","time":"5–8 yrs"},{"label":"CFO","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–40,000', 'BDT 80,000–150,000'),
  (2, 'Bank Relationship Officer', 'Banking', 'Finance', 'Relationship officers manage client accounts, process loans, and provide customer service at banks like Dutch-Bangla, BRAC Bank, and City Bank.', '["Customer Service","Loan Processing","CRM Software","Communication","Sales"]'::jsonb, '[{"label":"Trainee Officer","time":"0–1 yr"},{"label":"Relationship Officer","time":"1–3 yrs","current":true},{"label":"Senior Officer","time":"3–5 yrs"},{"label":"Branch Manager","time":"5–8 yrs"},{"label":"Regional Manager","time":"8+ yrs"}]'::jsonb, 'BDT 22,000–35,000', 'BDT 70,000–120,000'),
  (3, 'Audit Associate', 'Auditing', 'Finance', 'Audit associates work at firms like ACNABIN, Rahman Rahman Huq, and KPMG Bangladesh, checking financial records for accuracy and compliance.', '["Auditing Standards","Attention to Detail","Accounting Software","Analytical Thinking","Report Writing"]'::jsonb, '[{"label":"Audit Trainee","time":"0–1 yr"},{"label":"Audit Associate","time":"1–3 yrs","current":true},{"label":"Senior Auditor","time":"3–5 yrs"},{"label":"Audit Manager","time":"5–8 yrs"},{"label":"Partner","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–32,000', 'BDT 80,000–150,000'),
  (4, 'Tax Consultant', 'Taxation', 'Finance', 'Tax consultants help individuals and companies file taxes, plan tax strategies, and comply with Bangladesh tax laws.', '["Tax Laws","Compliance","Client Management","Analytical Skills","Communication"]'::jsonb, '[{"label":"Tax Trainee","time":"0–1 yr"},{"label":"Tax Consultant","time":"1–3 yrs","current":true},{"label":"Senior Consultant","time":"3–5 yrs"},{"label":"Tax Manager","time":"5–8 yrs"},{"label":"Tax Partner","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–38,000', 'BDT 90,000–180,000'),
  (5, 'Investment Analyst', 'Investment', 'Finance', 'Investment analysts research stocks, bonds, and other investments for brokerage firms and asset management companies in Bangladesh.', '["Financial Research","Stock Market","Valuation","Bloomberg Terminal","Risk Assessment"]'::jsonb, '[{"label":"Research Assistant","time":"0–1 yr"},{"label":"Investment Analyst","time":"1–3 yrs","current":true},{"label":"Senior Analyst","time":"3–5 yrs"},{"label":"Portfolio Manager","time":"5–8 yrs"},{"label":"Investment Director","time":"8+ yrs"}]'::jsonb, 'BDT 30,000–45,000', 'BDT 100,000–200,000'),
  (6, 'Credit Risk Officer', 'Risk Management', 'Finance', 'Credit risk officers evaluate loan applications, assess borrower risk, and set credit limits for banks and financial institutions.', '["Risk Assessment","Credit Scoring","Financial Analysis","Regulatory Knowledge","Decision Making"]'::jsonb, '[{"label":"Credit Trainee","time":"0–1 yr"},{"label":"Credit Officer","time":"1–3 yrs","current":true},{"label":"Senior Credit Officer","time":"3–5 yrs"},{"label":"Credit Manager","time":"5–8 yrs"},{"label":"Chief Risk Officer","time":"8+ yrs"}]'::jsonb, 'BDT 28,000–42,000', 'BDT 90,000–160,000'),
  (7, 'Accounts Executive', 'Accounting', 'Finance', 'Accounts executives manage day-to-day bookkeeping, prepare financial statements, and handle accounts payable/receivable for companies.', '["Bookkeeping","Tally/QuickBooks","Invoice Processing","Reconciliation","Financial Reporting"]'::jsonb, '[{"label":"Accounts Assistant","time":"0–1 yr"},{"label":"Accounts Executive","time":"1–3 yrs","current":true},{"label":"Senior Accountant","time":"3–5 yrs"},{"label":"Finance Controller","time":"5–8 yrs"},{"label":"Finance Director","time":"8+ yrs"}]'::jsonb, 'BDT 18,000–30,000', 'BDT 60,000–100,000'),
  (8, 'Treasury Analyst', 'Treasury', 'Finance', 'Treasury analysts manage company cash flow, foreign exchange exposure, and banking relationships for large corporations in Bangladesh.', '["Cash Management","Forex","Banking","Excel","Financial Markets"]'::jsonb, '[{"label":"Treasury Assistant","time":"0–1 yr"},{"label":"Treasury Analyst","time":"1–3 yrs","current":true},{"label":"Senior Treasury Analyst","time":"3–5 yrs"},{"label":"Treasury Manager","time":"5–8 yrs"},{"label":"Group Treasurer","time":"8+ yrs"}]'::jsonb, 'BDT 30,000–50,000', 'BDT 100,000–180,000'),
  (9, 'Microfinance Officer', 'Microfinance', 'Finance', 'Microfinance officers work with NGOs like BRAC, ASA, and Grameen Bank to provide small loans to rural entrepreneurs.', '["Field Work","Client Assessment","Loan Recovery","Community Relations","Documentation"]'::jsonb, '[{"label":"Field Officer","time":"0–1 yr"},{"label":"Microfinance Officer","time":"1–3 yrs","current":true},{"label":"Branch Manager","time":"3–5 yrs"},{"label":"Area Manager","time":"5–8 yrs"},{"label":"Regional Director","time":"8+ yrs"}]'::jsonb, 'BDT 15,000–25,000', 'BDT 50,000–80,000'),
  (10, 'Insurance Underwriter', 'Insurance', 'Finance', 'Underwriters evaluate insurance applications, assess risk, and determine coverage amounts for life, health, and property insurance.', '["Risk Assessment","Insurance Policies","Data Analysis","Medical Terminology","Legal Knowledge"]'::jsonb, '[{"label":"Underwriting Trainee","time":"0–1 yr"},{"label":"Underwriter","time":"1–3 yrs","current":true},{"label":"Senior Underwriter","time":"3–5 yrs"},{"label":"Underwriting Manager","time":"5–8 yrs"},{"label":"Chief Underwriter","time":"8+ yrs"}]'::jsonb, 'BDT 22,000–35,000', 'BDT 70,000–130,000'),
  (11, 'Software Engineer', 'Technology', 'IT', 'Software engineers design, code, and maintain applications for companies like Pathao, Shohoz, and numerous software outsourcing firms in Bangladesh.', '["JavaScript","React","Node.js","PostgreSQL","Git","REST APIs"]'::jsonb, '[{"label":"Junior Developer","time":"0–1 yr"},{"label":"Software Engineer","time":"1–3 yrs","current":true},{"label":"Senior Engineer","time":"3–6 yrs"},{"label":"Tech Lead","time":"6–9 yrs"},{"label":"CTO","time":"9+ yrs"}]'::jsonb, 'BDT 30,000–55,000', 'BDT 120,000–250,000'),
  (12, 'Frontend Developer', 'Technology', 'IT', 'Frontend developers build user interfaces for websites and web applications using HTML, CSS, and JavaScript frameworks.', '["React","Vue.js","HTML/CSS","JavaScript","Responsive Design","Figma"]'::jsonb, '[{"label":"Junior Frontend","time":"0–1 yr"},{"label":"Frontend Developer","time":"1–3 yrs","current":true},{"label":"Senior Frontend","time":"3–5 yrs"},{"label":"Frontend Lead","time":"5–8 yrs"},{"label":"UI/UX Director","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–45,000', 'BDT 100,000–200,000'),
  (13, 'Backend Developer', 'Technology', 'IT', 'Backend developers build server-side logic, databases, and APIs that power web and mobile applications.', '["Python/Django","Node.js","SQL","API Design","Server Management","Security"]'::jsonb, '[{"label":"Junior Backend","time":"0–1 yr"},{"label":"Backend Developer","time":"1–3 yrs","current":true},{"label":"Senior Backend","time":"3–5 yrs"},{"label":"Backend Architect","time":"5–8 yrs"},{"label":"Engineering Manager","time":"8+ yrs"}]'::jsonb, 'BDT 28,000–50,000', 'BDT 110,000–220,000'),
  (14, 'DevOps Engineer', 'Technology', 'IT', 'DevOps engineers manage deployment pipelines, cloud infrastructure, and system reliability for tech companies.', '["AWS/GCP","Docker","Kubernetes","CI/CD","Linux","Monitoring Tools"]'::jsonb, '[{"label":"Junior DevOps","time":"0–1 yr"},{"label":"DevOps Engineer","time":"1–3 yrs","current":true},{"label":"Senior DevOps","time":"3–5 yrs"},{"label":"Platform Architect","time":"5–8 yrs"},{"label":"Head of Infrastructure","time":"8+ yrs"}]'::jsonb, 'BDT 35,000–60,000', 'BDT 130,000–250,000'),
  (15, 'Data Analyst', 'Data', 'IT', 'Data analysts collect, process, and analyse data to help businesses make informed decisions.', '["SQL","Python","Excel","Tableau","Statistical Analysis","Data Visualization"]'::jsonb, '[{"label":"Junior Data Analyst","time":"0–1 yr"},{"label":"Data Analyst","time":"1–3 yrs","current":true},{"label":"Senior Data Analyst","time":"3–5 yrs"},{"label":"Data Scientist","time":"5–8 yrs"},{"label":"Head of Data","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–45,000', 'BDT 100,000–200,000'),
  (16, 'QA Engineer', 'Quality Assurance', 'IT', 'QA engineers test software, find bugs, and ensure product quality before release.', '["Manual Testing","Automation","Selenium","Bug Tracking","Test Cases","Attention to Detail"]'::jsonb, '[{"label":"Junior QA","time":"0–1 yr"},{"label":"QA Engineer","time":"1–3 yrs","current":true},{"label":"Senior QA","time":"3–5 yrs"},{"label":"QA Lead","time":"5–8 yrs"},{"label":"QA Director","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 80,000–150,000'),
  (17, 'Database Administrator', 'Database', 'IT', 'DBAs manage, secure, and optimise databases for organisations.', '["PostgreSQL","MySQL","MongoDB","Backup/Recovery","Performance Tuning","Security"]'::jsonb, '[{"label":"Junior DBA","time":"0–1 yr"},{"label":"DBA","time":"1–3 yrs","current":true},{"label":"Senior DBA","time":"3–5 yrs"},{"label":"Database Architect","time":"5–8 yrs"},{"label":"Data Platform Lead","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–45,000', 'BDT 100,000–180,000'),
  (18, 'Cybersecurity Analyst', 'Security', 'IT', 'Cybersecurity analysts protect organisations from cyber threats, monitor systems, and respond to incidents.', '["Network Security","Vulnerability Assessment","SIEM Tools","Risk Management","Ethical Hacking"]'::jsonb, '[{"label":"Security Trainee","time":"0–1 yr"},{"label":"Security Analyst","time":"1–3 yrs","current":true},{"label":"Senior Security Analyst","time":"3–5 yrs"},{"label":"Security Manager","time":"5–8 yrs"},{"label":"CISO","time":"8+ yrs"}]'::jsonb, 'BDT 30,000–55,000', 'BDT 120,000–250,000'),
  (19, 'IT Support Specialist', 'IT Support', 'IT', 'IT support specialists help users with technical issues, maintain hardware, and manage networks.', '["Hardware Troubleshooting","Networking","Windows/Linux","Customer Service","Ticketing Systems"]'::jsonb, '[{"label":"IT Support Level 1","time":"0–1 yr"},{"label":"IT Support Specialist","time":"1–3 yrs","current":true},{"label":"Senior IT Support","time":"3–5 yrs"},{"label":"IT Manager","time":"5–8 yrs"},{"label":"IT Director","time":"8+ yrs"}]'::jsonb, 'BDT 18,000–30,000', 'BDT 60,000–100,000'),
  (20, 'Mobile App Developer', 'Mobile Development', 'IT', 'Mobile developers build Android and iOS apps for Bangladeshi startups and enterprises.', '["Flutter","React Native","Android","iOS","App Store Deployment","REST APIs"]'::jsonb, '[{"label":"Junior Mobile Dev","time":"0–1 yr"},{"label":"Mobile Developer","time":"1–3 yrs","current":true},{"label":"Senior Mobile Dev","time":"3–5 yrs"},{"label":"Mobile Tech Lead","time":"5–8 yrs"},{"label":"Head of Mobile","time":"8+ yrs"}]'::jsonb, 'BDT 28,000–50,000', 'BDT 110,000–220,000'),
  (21, 'Civil Engineer', 'Construction', 'Engineering', 'Civil engineers design and oversee construction of roads, bridges, buildings, and infrastructure projects.', '["AutoCAD","Structural Analysis","Project Management","Site Supervision","Cost Estimation"]'::jsonb, '[{"label":"Site Engineer","time":"0–2 yrs"},{"label":"Civil Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Project Manager","time":"7–10 yrs"},{"label":"Chief Engineer","time":"10+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 70,000–130,000'),
  (22, 'Electrical Engineer', 'Power and Energy', 'Engineering', 'Electrical engineers design, test, and maintain electrical systems for buildings, factories, and power plants.', '["Circuit Design","Power Systems","AutoCAD Electrical","PLC Programming","Safety Standards"]'::jsonb, '[{"label":"Junior Engineer","time":"0–2 yrs"},{"label":"Electrical Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Project Manager","time":"7–10 yrs"},{"label":"Chief Engineer","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 65,000–120,000'),
  (23, 'Mechanical Engineer', 'Manufacturing', 'Engineering', 'Mechanical engineers design and maintain machinery, HVAC systems, and production equipment for factories.', '["SolidWorks","Thermodynamics","Manufacturing Processes","Maintenance","CAD"]'::jsonb, '[{"label":"Junior Engineer","time":"0–2 yrs"},{"label":"Mechanical Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Plant Manager","time":"7–10 yrs"},{"label":"Operations Director","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 65,000–120,000'),
  (24, 'Chemical Engineer', 'Pharmaceuticals', 'Engineering', 'Chemical engineers work in pharmaceutical, textile, and fertilizer plants, designing chemical processes.', '["Process Design","Safety Protocols","Quality Control","Thermodynamics","Lab Equipment"]'::jsonb, '[{"label":"Process Trainee","time":"0–2 yrs"},{"label":"Chemical Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Production Manager","time":"7–10 yrs"},{"label":"Plant Director","time":"10+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 70,000–130,000'),
  (25, 'Textile Engineer', 'Textile', 'Engineering', 'Textile engineers work in Bangladesh''s largest export industry, managing production and quality control.', '["Fabric Production","Quality Control","Dyeing Processes","Supply Chain","Factory Management"]'::jsonb, '[{"label":"Production Trainee","time":"0–2 yrs"},{"label":"Textile Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Production Manager","time":"7–10 yrs"},{"label":"Factory Director","time":"10+ yrs"}]'::jsonb, 'BDT 18,000–32,000', 'BDT 60,000–110,000'),
  (26, 'Industrial Engineer', 'Manufacturing', 'Engineering', 'Industrial engineers optimise production processes, reduce waste, and improve efficiency.', '["Process Optimization","Six Sigma","Supply Chain","Data Analysis","Lean Manufacturing"]'::jsonb, '[{"label":"Junior IE","time":"0–2 yrs"},{"label":"Industrial Engineer","time":"2–4 yrs","current":true},{"label":"Senior IE","time":"4–7 yrs"},{"label":"Operations Manager","time":"7–10 yrs"},{"label":"COO","time":"10+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 70,000–130,000'),
  (27, 'Environmental Engineer', 'Environment', 'Engineering', 'Environmental engineers work on waste management, pollution control, and sustainability projects.', '["Environmental Impact Assessment","Waste Management","Water Treatment","Compliance","Field Work"]'::jsonb, '[{"label":"Junior Engineer","time":"0–2 yrs"},{"label":"Environmental Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Project Manager","time":"7–10 yrs"},{"label":"Director of EHS","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 65,000–120,000'),
  (28, 'Telecommunication Engineer', 'Telecom', 'Engineering', 'Telecom engineers design and maintain mobile networks, fibre optics, and communication systems.', '["Network Design","RF Engineering","Fiber Optics","Signal Processing","Troubleshooting"]'::jsonb, '[{"label":"Network Trainee","time":"0–2 yrs"},{"label":"Telecom Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Network Manager","time":"7–10 yrs"},{"label":"CTO","time":"10+ yrs"}]'::jsonb, 'BDT 25,000–42,000', 'BDT 80,000–150,000'),
  (29, 'Automobile Engineer', 'Automotive', 'Engineering', 'Automobile engineers work in vehicle assembly, maintenance, and design for automotive companies.', '["Vehicle Systems","Diagnostics","CAD","Mechanical Repair","Quality Assurance"]'::jsonb, '[{"label":"Service Engineer","time":"0–2 yrs"},{"label":"Automobile Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Service Manager","time":"7–10 yrs"},{"label":"Operations Director","time":"10+ yrs"}]'::jsonb, 'BDT 18,000–32,000', 'BDT 60,000–110,000'),
  (30, 'Marine Engineer', 'Maritime', 'Engineering', 'Marine engineers work on ships, ports, and maritime operations in Chattogram and Dhaka.', '["Ship Systems","Marine Safety","Maintenance","Navigation Systems","Regulatory Compliance"]'::jsonb, '[{"label":"Junior Engineer","time":"0–2 yrs"},{"label":"Marine Engineer","time":"2–4 yrs","current":true},{"label":"Senior Engineer","time":"4–7 yrs"},{"label":"Chief Engineer","time":"7–10 yrs"},{"label":"Fleet Manager","time":"10+ yrs"}]'::jsonb, 'BDT 30,000–50,000', 'BDT 100,000–200,000'),
  (31, 'Marketing Executive', 'Marketing', 'Business', 'Marketing executives plan and execute campaigns, manage social media, and analyse market trends.', '["Digital Marketing","Social Media","Market Research","Campaign Management","Analytics"]'::jsonb, '[{"label":"Marketing Trainee","time":"0–1 yr"},{"label":"Marketing Executive","time":"1–3 yrs","current":true},{"label":"Senior Executive","time":"3–5 yrs"},{"label":"Brand Manager","time":"5–8 yrs"},{"label":"Marketing Director","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 80,000–160,000'),
  (32, 'HR Executive', 'Human Resources', 'Business', 'HR executives handle recruitment, onboarding, payroll, and employee relations.', '["Recruitment","Payroll","Labour Laws","Communication","Employee Engagement"]'::jsonb, '[{"label":"HR Trainee","time":"0–1 yr"},{"label":"HR Executive","time":"1–3 yrs","current":true},{"label":"Senior HR Executive","time":"3–5 yrs"},{"label":"HR Manager","time":"5–8 yrs"},{"label":"HR Director","time":"8+ yrs"}]'::jsonb, 'BDT 18,000–30,000', 'BDT 70,000–130,000'),
  (33, 'Business Development Officer', 'Sales', 'Business', 'BDOs identify new business opportunities, build client relationships, and drive revenue growth.', '["Sales","Negotiation","Client Relationship","Market Research","Communication"]'::jsonb, '[{"label":"Sales Trainee","time":"0–1 yr"},{"label":"BDO","time":"1–3 yrs","current":true},{"label":"Senior BDO","time":"3–5 yrs"},{"label":"Sales Manager","time":"5–8 yrs"},{"label":"Sales Director","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 80,000–200,000'),
  (34, 'Supply Chain Officer', 'Logistics', 'Business', 'Supply chain officers manage procurement, warehousing, and distribution for manufacturing and retail companies.', '["Procurement","Logistics","Inventory Management","Vendor Relations","ERP Systems"]'::jsonb, '[{"label":"Supply Chain Trainee","time":"0–1 yr"},{"label":"Supply Chain Officer","time":"1–3 yrs","current":true},{"label":"Senior Officer","time":"3–5 yrs"},{"label":"Supply Chain Manager","time":"5–8 yrs"},{"label":"Logistics Director","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 80,000–150,000'),
  (35, 'Operations Executive', 'Operations', 'Business', 'Operations executives ensure smooth day-to-day business operations and process efficiency.', '["Process Improvement","Team Management","Problem Solving","Reporting","Coordination"]'::jsonb, '[{"label":"Operations Trainee","time":"0–1 yr"},{"label":"Operations Executive","time":"1–3 yrs","current":true},{"label":"Senior Executive","time":"3–5 yrs"},{"label":"Operations Manager","time":"5–8 yrs"},{"label":"COO","time":"8+ yrs"}]'::jsonb, 'BDT 18,000–32,000', 'BDT 70,000–140,000'),
  (36, 'Export-Import Officer', 'International Trade', 'Business', 'Export-Import officers manage customs, documentation, and international shipping for trading companies.', '["Customs Documentation","LC Process","International Trade Laws","Freight Forwarding","Negotiation"]'::jsonb, '[{"label":"Trade Trainee","time":"0–1 yr"},{"label":"Export-Import Officer","time":"1–3 yrs","current":true},{"label":"Senior Officer","time":"3–5 yrs"},{"label":"Trade Manager","time":"5–8 yrs"},{"label":"Trade Director","time":"8+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 80,000–160,000'),
  (37, 'Customer Success Manager', 'Customer Service', 'Business', 'CSMs ensure customer satisfaction, retention, and loyalty for tech and service companies.', '["Customer Service","Problem Solving","Communication","CRM Software","Retention Strategies"]'::jsonb, '[{"label":"Customer Support","time":"0–1 yr"},{"label":"CSM","time":"1–3 yrs","current":true},{"label":"Senior CSM","time":"3–5 yrs"},{"label":"Customer Success Lead","time":"5–8 yrs"},{"label":"Head of Customer Success","time":"8+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 80,000–150,000'),
  (38, 'Project Coordinator', 'Project Management', 'Business', 'Project coordinators help plan, track, and deliver projects across various industries.', '["Project Planning","MS Project","Communication","Risk Management","Budget Tracking"]'::jsonb, '[{"label":"Project Assistant","time":"0–1 yr"},{"label":"Project Coordinator","time":"1–3 yrs","current":true},{"label":"Project Manager","time":"3–5 yrs"},{"label":"Senior PM","time":"5–8 yrs"},{"label":"Program Director","time":"8+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 80,000–160,000'),
  (39, 'E-commerce Manager', 'E-commerce', 'Business', 'E-commerce managers oversee online stores, manage product listings, and drive sales for platforms like Daraz, Chaldal, and others.', '["E-commerce Platforms","Digital Marketing","Inventory Management","Customer Experience","Analytics"]'::jsonb, '[{"label":"E-commerce Assistant","time":"0–1 yr"},{"label":"E-commerce Manager","time":"1–3 yrs","current":true},{"label":"Senior Manager","time":"3–5 yrs"},{"label":"Head of E-commerce","time":"5–8 yrs"},{"label":"VP of Digital Commerce","time":"8+ yrs"}]'::jsonb, 'BDT 25,000–45,000', 'BDT 100,000–200,000'),
  (40, 'Management Trainee', 'Management', 'Business', 'MT programs at Grameenphone, Unilever, BAT, and other multinationals train future leaders.', '["Leadership","Problem Solving","Analytical Thinking","Communication","Teamwork"]'::jsonb, '[{"label":"Management Trainee","time":"0–1 yr","current":true},{"label":"Assistant Manager","time":"1–3 yrs"},{"label":"Deputy Manager","time":"3–5 yrs"},{"label":"Manager","time":"5–8 yrs"},{"label":"Director","time":"8+ yrs"}]'::jsonb, 'BDT 40,000–60,000', 'BDT 150,000–250,000'),
  (41, 'Research Associate', 'Research', 'Science', 'Research associates work at icddr,b, BARI, BRRI, and university research centres.', '["Research Methodology","Data Analysis","Scientific Writing","Lab Techniques","Statistics"]'::jsonb, '[{"label":"Research Assistant","time":"0–2 yrs"},{"label":"Research Associate","time":"2–4 yrs","current":true},{"label":"Senior Researcher","time":"4–7 yrs"},{"label":"Research Scientist","time":"7–10 yrs"},{"label":"Principal Scientist","time":"10+ yrs"}]'::jsonb, 'BDT 25,000–42,000', 'BDT 75,000–140,000'),
  (42, 'Biomedical Scientist', 'Healthcare', 'Science', 'Biomedical scientists work in hospital labs, diagnostic centres, and pharmaceutical companies.', '["Lab Testing","Microscopy","Pathology","Quality Control","Medical Terminology"]'::jsonb, '[{"label":"Lab Assistant","time":"0–2 yrs"},{"label":"Biomedical Scientist","time":"2–4 yrs","current":true},{"label":"Senior Scientist","time":"4–7 yrs"},{"label":"Lab Manager","time":"7–10 yrs"},{"label":"Director of Lab Services","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 60,000–110,000'),
  (43, 'Quality Control Officer', 'Pharmaceuticals', 'Science', 'QC officers test raw materials and finished products at Square, Beximco, and other pharma companies.', '["GMP Standards","Lab Testing","Documentation","Analytical Chemistry","Attention to Detail"]'::jsonb, '[{"label":"QC Trainee","time":"0–2 yrs"},{"label":"QC Officer","time":"2–4 yrs","current":true},{"label":"Senior QC Officer","time":"4–7 yrs"},{"label":"QC Manager","time":"7–10 yrs"},{"label":"Quality Director","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 65,000–120,000'),
  (44, 'Environmental Scientist', 'Environment', 'Science', 'Environmental scientists work on conservation, pollution monitoring, and climate change projects.', '["Field Sampling","Data Analysis","Environmental Laws","Report Writing","GIS"]'::jsonb, '[{"label":"Field Assistant","time":"0–2 yrs"},{"label":"Environmental Scientist","time":"2–4 yrs","current":true},{"label":"Senior Scientist","time":"4–7 yrs"},{"label":"Project Manager","time":"7–10 yrs"},{"label":"Director","time":"10+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 70,000–130,000'),
  (45, 'Microbiologist', 'Microbiology', 'Science', 'Microbiologists work in food safety, pharmaceutical labs, and clinical diagnostics.', '["Culture Techniques","Sterilization","Microscopy","Lab Safety","Data Recording"]'::jsonb, '[{"label":"Lab Technician","time":"0–2 yrs"},{"label":"Microbiologist","time":"2–4 yrs","current":true},{"label":"Senior Microbiologist","time":"4–7 yrs"},{"label":"Lab Manager","time":"7–10 yrs"},{"label":"Scientific Director","time":"10+ yrs"}]'::jsonb, 'BDT 20,000–35,000', 'BDT 65,000–120,000'),
  (46, 'Food Scientist', 'Food', 'Science', 'Food scientists develop new food products, ensure safety, and improve quality for food companies.', '["Food Safety","Product Development","Quality Assurance","Sensory Evaluation","Regulations"]'::jsonb, '[{"label":"Quality Trainee","time":"0–2 yrs"},{"label":"Food Scientist","time":"2–4 yrs","current":true},{"label":"Senior Food Scientist","time":"4–7 yrs"},{"label":"R&D Manager","time":"7–10 yrs"},{"label":"Technical Director","time":"10+ yrs"}]'::jsonb, 'BDT 22,000–38,000', 'BDT 70,000–130,000'),
  (47, 'Genetic Counselor', 'Genetics', 'Science', 'Genetic counselors work in hospitals and diagnostic labs, advising patients on genetic conditions.', '["Genetics Knowledge","Patient Counseling","Risk Assessment","Medical Ethics","Communication"]'::jsonb, '[{"label":"Genetic Assistant","time":"0–2 yrs"},{"label":"Genetic Counselor","time":"2–4 yrs","current":true},{"label":"Senior Counselor","time":"4–7 yrs"},{"label":"Clinic Manager","time":"7–10 yrs"},{"label":"Director of Genetics","time":"10+ yrs"}]'::jsonb, 'BDT 30,000–50,000', 'BDT 90,000–160,000'),
