INSERT INTO alumni (id, full_name, institution, discipline, graduation_year, "current_role", industry, bio, image_initials, consent_given, is_published) VALUES
  (1, 'Sadia Rahman', 'BUET', 'Engineering', 2022, 'Software Engineer', 'Technology', 'Sadia works at Pathao as a backend developer. She specializes in Node.js and microservices architecture. During university, she led the BUET Coding Club and interned at SELISE Digital Platforms.', 'SR', TRUE, TRUE),
  (2, 'Rakib Hasan', 'North South University', 'Finance', 2021, 'Financial Analyst', 'Banking and Finance', 'Rakib is a Financial Analyst at BRAC Bank. He completed his CFA Level 2 and previously interned at Standard Chartered Bank. He advises students to focus on financial modeling and Excel skills.', 'RH', TRUE, TRUE),
  (3, 'Tania Akter', 'University of Dhaka', 'Science', 2020, 'Research Associate', 'Research', 'Tania works at icddr,b as a Research Associate in the Infectious Diseases division. She has co-authored 3 research papers and is pursuing her Master''s in Public Health.', 'TA', TRUE, TRUE),
  (4, 'Mehedi Islam', 'RUET', 'Engineering', 2019, 'Project Manager', 'Construction', 'Mehedi manages infrastructure projects at Rangs Properties Ltd. He has overseen 5 major residential projects in Dhaka and specializes in project planning and cost estimation.', 'MI', TRUE, TRUE),
  (5, 'Nusrat Jahan', 'University of Chittagong', 'Business', 2021, 'Marketing Executive', 'Marketing', 'Nusrat works at Unilever Bangladesh as a Brand Executive. She manages the Lifebuoy brand and has led successful digital campaigns reaching millions of customers.', 'NJ', TRUE, TRUE),
  (6, 'Arif Chowdhury', 'IUB', 'IT', 2022, 'Frontend Developer', 'Technology', 'Arif is a Frontend Developer at Shohoz. He is passionate about React and building user-friendly interfaces. He also mentors students at his former university.', 'AC', TRUE, TRUE),
  (7, 'Farzana Haque', 'Jahangirnagar University', 'Arts', 2020, 'Content Strategist', 'Media', 'Farzana leads content strategy at The Daily Star''s digital wing. She creates engaging content for social media and has grown their Instagram following to 500k.', 'FH', TRUE, TRUE),
